//! Human-verified golden harness (R5, Sprint 99).
//!
//! Unlike the paired `moel_*.md` golden files — which are *machine-generated by
//! hwp2md itself* and therefore only catch output drift, not correctness — the
//! golden compared here is authored by a human who verified the source `.hwp`
//! against a trusted viewer (한컴오피스). It breaks the self-referential loop:
//! a discrepancy is a real conversion bug, not just a changed output.
//!
//! The verified golden does not exist until a human creates it. See
//! `tests/fixtures/real/HUMAN_VERIFY.md` for the procedure and the list of
//! already-confirmed discrepancies (heading inconsistency, double numbering,
//! heading-includes-body). Until then this test is `#[ignore]`d and, when run
//! with `--ignored`, skips gracefully if the file is absent.
//!
//! Run once the verified golden exists:
//!   cargo test --test real_human_golden -- --ignored

use std::path::Path;

use hwp2md::{hwp, md};

const FIXTURES_DIR: &str = "tests/fixtures/real";
const STEM: &str = "moel_02_vocational_training";
const VERIFIED: &str = "moel_02.human-verified.md";

#[test]
#[ignore = "requires a human-verified golden (tests/fixtures/real/moel_02.human-verified.md)"]
fn moel_02_matches_human_verified_golden() {
    let verified_path = Path::new(FIXTURES_DIR).join(VERIFIED);
    let Ok(expected) = std::fs::read_to_string(&verified_path) else {
        eprintln!(
            "SKIP: {} not found. Create it per tests/fixtures/real/HUMAN_VERIFY.md \
             to enable non-self-referential correctness checking.",
            verified_path.display()
        );
        return;
    };

    let hwp_path = Path::new(FIXTURES_DIR).join(format!("{STEM}.hwp"));
    let doc = hwp::read_hwp(&hwp_path)
        .unwrap_or_else(|e| panic!("read_hwp failed for {STEM}.hwp: {e}"));
    let actual = md::write_markdown(&doc, false);

    if actual != expected {
        // Surface the first differing line to make the real bug obvious.
        let first_diff = actual
            .lines()
            .zip(expected.lines())
            .enumerate()
            .find(|(_, (a, e))| a != e);
        if let Some((n, (a, e))) = first_diff {
            panic!(
                "human-verified golden mismatch at line {}:\n  actual:   {a:?}\n  expected: {e:?}",
                n + 1
            );
        }
        panic!(
            "human-verified golden mismatch: line counts differ \
             (actual {}, expected {})",
            actual.lines().count(),
            expected.lines().count()
        );
    }
}
